<?php
require_once '../config/db.php';if(session_status()===PHP_SESSION_NONE)session_start();if(!isset($_SESSION['user_id']))redirect('../index.php');$notice=$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['add_journal'])){verify_csrf();try{$amount=round((float)$_POST['amount'],2);$debit=(int)$_POST['debit_account'];$credit=(int)$_POST['credit_account'];if($amount<=0||!$debit||!$credit||$debit===$credit)throw new RuntimeException('Choose two different accounts and a valid amount.');$pdo->beginTransaction();post_journal($pdo,$_POST['entry_date'],trim((string)$_POST['reference_number']),trim((string)$_POST['description']),[['account_id'=>$debit,'debit'=>$amount,'credit'=>0],['account_id'=>$credit,'debit'=>0,'credit'=>$amount]]);$pdo->commit();redirect('journal.php?saved=1');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$accounts=$pdo->query('SELECT id,account_code,name,type FROM chart_of_accounts WHERE is_active=1 ORDER BY account_code')->fetchAll();$entries=$pdo->query("SELECT je.*,u.username,COALESCE(SUM(jl.debit),0) total FROM journal_entries je LEFT JOIN journal_lines jl ON jl.journal_entry_id=je.id LEFT JOIN users u ON u.id=je.created_by GROUP BY je.id ORDER BY je.entry_date DESC,je.id DESC LIMIT 100")->fetchAll();$balances=$pdo->query("SELECT c.account_code,c.name,c.type,COALESCE(SUM(j.debit-j.credit),0) balance FROM chart_of_accounts c LEFT JOIN journal_lines j ON j.account_id=c.id LEFT JOIN journal_entries e ON e.id=j.journal_entry_id AND e.status='posted' WHERE c.is_active=1 GROUP BY c.id ORDER BY c.account_code")->fetchAll();require_once 'includes/header.php';require_once 'includes/sidebar.php';
?>
<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex items-center gap-4 sticky top-0 z-10"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><div><h2 class="text-2xl font-bold">General ledger</h2><p class="text-sm text-slate-500">Double-entry journals and chart of accounts</p></div></header><div class="p-5 md:p-8 max-w-7xl mx-auto"><?php if(isset($_GET['saved'])):?><div class="bg-emerald-50 border p-4 rounded-xl mb-5">Balanced journal posted.</div><?php endif;?><?php if($error):?><div class="bg-rose-50 text-rose-800 border p-4 rounded-xl mb-5"><?=h($error)?></div><?php endif;?>
<div class="grid xl:grid-cols-3 gap-7"><form method="post" class="bg-white border rounded-2xl p-6 h-fit space-y-4"><?=csrf_field()?><h3 class="font-bold text-lg">Manual journal</h3><label class="block text-sm">Date<input name="entry_date" type="date" value="<?=date('Y-m-d')?>" required class="mt-1 w-full border rounded-lg px-3 py-2"></label><label class="block text-sm">Reference<input name="reference_number" required class="mt-1 w-full border rounded-lg px-3 py-2"></label><label class="block text-sm">Description<textarea name="description" required class="mt-1 w-full border rounded-lg px-3 py-2"></textarea></label><label class="block text-sm">Debit account<select name="debit_account" required class="mt-1 w-full border rounded-lg px-3 py-2 bg-white"><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=h($a['account_code'].' · '.$a['name'])?></option><?php endforeach;?></select></label><label class="block text-sm">Credit account<select name="credit_account" required class="mt-1 w-full border rounded-lg px-3 py-2 bg-white"><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=h($a['account_code'].' · '.$a['name'])?></option><?php endforeach;?></select></label><label class="block text-sm">Amount<input name="amount" type="number" min="0.01" step="0.01" required class="mt-1 w-full border rounded-lg px-3 py-2"></label><button name="add_journal" class="brand-bg text-white px-5 py-2.5 rounded-lg font-semibold w-full">Post journal</button></form>
<div class="xl:col-span-2 space-y-7"><section class="bg-white border rounded-2xl overflow-hidden"><div class="p-5 border-b"><h3 class="font-bold">Account balances</h3></div><div class="max-h-80 overflow-y-auto"><table class="w-full text-sm"><thead class="bg-slate-50 sticky top-0"><tr><th class="text-left p-3">Code</th><th class="text-left p-3">Account</th><th class="text-left p-3">Type</th><th class="text-right p-3">Balance</th></tr></thead><tbody class="divide-y"><?php foreach($balances as $a):$normal=in_array($a['type'],['Liability','Equity','Revenue'],true)?-$a['balance']:$a['balance'];?><tr><td class="p-3 font-mono"><?=h($a['account_code'])?></td><td class="p-3 font-medium"><?=h($a['name'])?></td><td class="p-3 text-slate-500"><?=h($a['type'])?></td><td class="p-3 text-right money"><?=money($pdo,$normal)?></td></tr><?php endforeach;?></tbody></table></div></section><section class="bg-white border rounded-2xl overflow-hidden"><div class="p-5 border-b"><h3 class="font-bold">Recent journal entries</h3></div><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="text-left p-3">Date</th><th class="text-left p-3">Reference</th><th class="text-left p-3">Description</th><th class="text-right p-3">Amount</th></tr></thead><tbody class="divide-y"><?php foreach($entries as $e):?><tr><td class="p-3"><?=h($e['entry_date'])?></td><td class="p-3 font-semibold"><?=h($e['reference_number'])?></td><td class="p-3"><?=h($e['description'])?><span class="block text-xs text-slate-400"><?=h($e['source_type'])?></span></td><td class="p-3 text-right money"><?=money($pdo,$e['total'])?></td></tr><?php endforeach;?></tbody></table></section></div></div></div></main><?php require_once 'includes/footer.php';?>
